#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

struct Point {
    double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    // Per-thread local bins to avoid races; then combine safely.
    #pragma omp parallel
    {
        std::array<size_t, 4> local = {0u, 0u, 0u, 0u};

        #pragma omp for nowait
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Quadrants with axes included as "positive" side:
            // Q1: x>=0,y>=0 ; Q2: x<0,y>=0 ; Q3: x<0,y<0 ; Q4: x>=0,y<0
            if (x >= 0.0) {
                if (y >= 0.0) ++local[0]; // Q1
                else          ++local[3]; // Q4
            } else {
                if (y >= 0.0) ++local[1]; // Q2
                else          ++local[2]; // Q3
            }
        }

        #pragma omp critical
        {
            bins[0] += local[0];
            bins[1] += local[1];
            bins[2] += local[2];
            bins[3] += local[3];
        }
    }
}
